// --- PSYCHEDELIC VORTEX (Texture mode) ---
// Use sliders A and B to change the effect in real time!

// We set default values if the sliders are at 0
float speed = 5.0;    // animation speed
float scale = 20.0;   // pattern scale

// We move the center of the u,v coordinates to the center of the screen
vec2 center = vec2(u, v) - 0.5;
float dist = length(center);
float angle = atan(center.y, center.x);

// We compute the wave from the distance, the angle and the TIME (t)
float wave = sin(dist * scale - t * speed + angle * 4.0);

// Colori dinamici
float r = 0.5 + 0.5 * wave;
float g = 0.2 + 0.3 * sin(t); // The green pulses gently over time
float b = 0.5 + 0.5 * cos(dist * 10.0 - t);

return vec3(r, g, b);
